// The synodic-season gate (rule C3), in ONE place. A seasonal space - a comet,
// a seasonal asteroid - is only on the board while the Sunspot Cube sits in its
// season, so off-season nothing may route TO or THROUGH it.
//
// This rule USED to live at the bottom of data/node-tags.js, which is AUTO-
// GENERATED by scripts/gen-node-tags.mjs. The generator's template emits only
// NODE_TAGS + spriteForTags, so the next regeneration would have silently
// deleted the gate and broken every importer. Rule logic belongs in a
// hand-maintained module; node-tags.js stays pure data plus its sprite helper.

import { NODE_TAGS } from './node-tags.js';
import { SYNODIC_COMET_IDS } from './future-goals.js';

// Synodic season of a map node ('red' | 'yellow' | 'blue'), or null when the
// node is on the board year-round. The node tag is the single source of truth;
// the planner data's own siteSynodic is the fallback for nodes the tag table
// does not list.
export function nodeSeason(node) {
  if (!node) return null;
  return (NODE_TAGS[node.id2] && NODE_TAGS[node.id2].season) || node.siteSynodic || null;
}

// Is this map node one of the Synodic Comets?
//
// Match on `serverId` FIRST - the data/sites.js id the planner node resolved to
// through the name-alias table (planner-map.js). That is the only key that can
// be trusted: the vendored planner JSON and data/sites.js disagree on two of the
// nine comet names, and BOTH would slip through an id2 match.
//   - the planner names 103P/Hartley 2 "Comet Bartley 2" (an upstream typo), so
//     its id2 is `comet-bartley-2` while sites.js has `comet_hartley_2`
//   - the planner names 3200 Phaethon just "Phaethon", so its id2 is `phaethon`
//     while sites.js has `comet_phaethon`
// The alias table already reconciles both onto the right serverId. id2 / id stay
// as fallbacks for callers holding a node that never went through that match.
const SYNODIC_COMETS = new Set(SYNODIC_COMET_IDS);
export function isSynodicComet(node) {
  if (!node) return false;
  return SYNODIC_COMETS.has(node.serverId)
    || SYNODIC_COMETS.has(node.id2)
    || SYNODIC_COMETS.has(node.id);
}

// The gate itself.
//
// Three carve-outs, all load-bearing:
//   - The Venus flyby is never gated. Venus is always there; only its +N flyby
//     boost is blue-season, and that is handled where the boost is awarded.
//   - A ship ALREADY standing inside a season's region may keep moving within
//     it out of season, because it is not entering anything. The binary
//     asteroid Hermes forced this: its two halves are one object, and a mission
//     that must plant a factory on both could not hop between them once the
//     cube left their season (user 2026-08-01). The rule is written generally,
//     not as a Hermes special case - same season on both ends means you never
//     left the region, so there is nothing to re-enter.
//   - C3b Synodic Comets: "Exceptionally, a Rocket with an activated TW
//     thruster can enter or exit a Synodic Comet during any season." Pass
//     opts.twThruster to claim it. Deliberately NARROW on two axes, because a
//     wide reading would open the whole seasonal map:
//       * A COMET'S OWN APPARITION TRACK only. That is the comet plus the
//         same-season corridor it sits behind, tagged `synodicCometTrack` at
//         map-load (planner-map.js#markSynodicCometTracks - see the note there
//         for why the corridor has to be included, and why including it stays
//         narrow). The seasonal regions holding Icarus, Pholus, Bee Zed,
//         Asbolus, the Hermes pair and burn-79bta carry no comet, so C3b never
//         opens them.
//       * The DESTINATION only. Blocking only ever happens on the node being
//         entered, so waiving on toNode covers both halves of "enter or exit":
//         leaving an off-season comet for an unseasoned neighbour was never
//         gated, and comet-to-comet is covered by the destination being on a
//         track. Waiving on fromNode as well would let a TW rocket leave a
//         comet straight into an off-season ASTEROID, which C3b does not say.
//     The caller owns the "a Rocket, with that thruster ACTIVATED" half: only
//     the rocket's own route paths pass the flag, and only when the active
//     thruster is a GW thruster on its promoted (purple TW) face. A Freighter,
//     a Bernal, or a mobile Factory never gets it.
//
// `toNode` / `fromNode` are planner nodes; `solarSeason` is the cube's current
// season name. A null solarSeason (unknown) never blocks.
export function seasonEntryBlocked(toNode, fromNode, solarSeason, opts) {
  if (!toNode || !solarSeason) return false;
  if (toNode.type === 'venus') return false;
  const season = nodeSeason(toNode);
  if (!season || season === solarSeason) return false;
  if (nodeSeason(fromNode) === season) return false;
  if (opts && opts.twThruster && onSynodicCometTrack(toNode)) return false;
  return true;
}

// Is this node the comet itself, or on its apparition track? The track flag is
// stamped at map-load; the direct comet test is the fallback for a node that
// never went through that pass.
export function onSynodicCometTrack(node) {
  return !!(node && (node.synodicCometTrack || isSynodicComet(node)));
}
